package com.dndmaster.aigamemaster.application.scene;
import com.dndmaster.aigamemaster.application.GroundingViolationException; import java.util.Objects;
public final class ScenarioBoundSceneService{private final ScenarioPromptFactory prompts;private final SceneModelPort model;public ScenarioBoundSceneService(ScenarioPromptFactory prompts,SceneModelPort model){this.prompts=Objects.requireNonNull(prompts);this.model=Objects.requireNonNull(model);}public SceneOutput generate(ScenarioRequest request){SceneOutput output=model.generateScene(prompts.create(request));if(!output.scenarioId().equals(request.scenarioId())||!output.ruleSetId().equals(request.ruleSetId()))throw new GroundingViolationException("model output referenced unselected scenario or rule set");if(output.alignment()!=ScenarioAlignment.WITHIN_SELECTED_SCENARIO)throw new GroundingViolationException("original scenario expansion is forbidden");return output;}}
